import{CARE_THREADS}from './care-threads.js';
import{mix}from './world.js';
// Authored connected experiences; prerequisites prevent sentence-only combinatorial padding.
const choice=(id,text,result,delta,next)=>({id,text,result,delta,next});
export const THREADS=[
{id:'brush',min:120,homes:['family'],start:'사람이 바닥에 수건을 깔고 빗을 손등에 대어 보여 준다. 내 어깨에 잠깐 닿았다가 손이 멈춘다.',actions:[choice('near','사람 옆에 서서 짧게 몸을 맡긴다','빗이 몇 번 지나간 뒤 손이 멈췄다. 몸을 돌릴 공간은 그대로 남아 있다.',{familyBond:3,stress:-2},'practice'),choice('away','빗이 닿지 않는 쪽으로 한 걸음 비킨다','사람은 손을 거두고 오늘은 빗을 내려놓는다. 내 쪽에서 다시 다가갈 때까지 기다린다.',{stress:-2},'slow')],follow:{practice:{days:8,text:'빗을 꺼내는 날이면 수건 곁에 선다. 오늘도 짧게 빗고 쉬는 순서로 털을 돌본다.',delta:{comfort:3}},slow:{days:14,text:'사람은 빗을 바닥에 놓는 것부터 다시 시작한다. 몸에 닿지 않는 연습이 여러 날 쌓인다.',delta:{trust:2}}}},
{id:'settling-sounds',min:100,homes:['family'],condition:s=>!!s.lastAreaChange&&s.day-s.lastAreaChange.day<90,start:'새집 복도에서 엘리베이터가 멈추는 소리가 난다. 함께 사는 사람은 문을 열지 않고 방 안에 머문다.',actions:[choice('watch','문에서 떨어져 소리가 멎는 것을 살핀다','발소리가 지나가고 방 안은 다시 조용해졌다. 사람도 그대로 곁에 있다.',{stress:-3},'familiar'),choice('den','담요가 있는 안쪽으로 몸을 옮긴다','조용한 자리에서 몸을 낮췄다. 사람은 억지로 문 앞에 데려가지 않는다.',{comfort:2},'refuge')],follow:{familiar:{days:12,text:'복도에서 같은 소리가 났지만 몸을 일으키는 시간이 짧아졌다. 문이 열리지 않자 다시 눕는다.',delta:{stress:-3}},refuge:{days:10,text:'복도가 시끄러워지면 안쪽 담요를 찾는다. 소리가 줄면 스스로 밖으로 나와 물을 마신다.',delta:{comfort:3}}}},
{id:'child-boundary',min:180,homes:['family'],condition:s=>s.worldModel.care>=60,start:'방문한 어린 사람이 내 앞에서 손을 빠르게 움직인다. 함께 사는 어른이 곁에 앉아 손을 낮추도록 돕는다.',actions:[choice('near','어른 가까이에 서서 천천히 손을 확인한다','손이 낮아지자 잠깐 다가갔다. 어른은 몸을 붙잡지 않고 짧게 만남을 마쳤다.',{trust:2},'brief'),choice('retreat','사람들이 없는 잠자리로 물러난다','어른이 잠자리 앞을 비워 준다. 아무도 따라 들어오지 않아 조용히 쉰다.',{stress:-3},'safe')],follow:{brief:{days:30,text:'같은 방문자가 왔다. 이번에는 앉은 채 기다린다. 짧게 확인한 뒤 내 자리로 돌아갔다.',delta:{trust:2}},safe:{days:20,text:'방문자가 오는 날에는 잠자리 앞의 통로가 비워진다. 쉬는 동안 손이 따라오지 않는다.',delta:{comfort:3}}}},
{id:'water-route',min:120,homes:['street'],condition:s=>s.worldModel.care>=25,start:'늘 지나던 골목 끝에 물그릇이 놓였다. 그릇 옆에는 사람이 있고 반대편에는 넓게 돌아갈 길이 있다.',actions:[choice('drink','빈 쪽으로 돌아가 물을 마신다','사람은 움직이지 않았다. 물을 마신 뒤 골목 안쪽으로 돌아간다.',{comfort:3},'water'),choice('wait','사람이 자리를 비울 때까지 그늘에서 쉰다','한참 뒤 사람이 가고 그릇만 남았다. 주변을 살핀 뒤 다가갔다.',{stress:-2},'late')],follow:{water:{days:9,text:'같은 자리에 새 물이 놓여 있다. 붐비는 길을 피해 그쪽을 거치는 동선이 생겼다.',delta:{comfort:3}},late:{days:12,text:'사람이 적은 시간에 골목 끝을 지난다. 빈 물그릇은 다음 날 다시 채워져 있었다.',delta:{trust:1}}}},
{id:'shelter-rest',min:90,homes:['shelter'],condition:s=>s.environmentModel?.facility!=='petshop',start:'보호소 직원이 칸 앞에 가림 천을 조금 내려 준다. 복도의 다른 개들이 짖지만 잠자리 안쪽은 덜 밝다.',actions:[choice('rest','가려진 안쪽에 몸을 눕힌다','바깥 움직임이 덜 보여 고개를 들던 횟수가 줄었다. 잠깐 눈을 감는다.',{stress:-4},'quiet'),choice('watch','가림 천 옆에서 직원의 움직임을 본다','직원이 지나가다 멈춰 기다린다. 몸을 내밀지 않아도 물과 먹이를 챙겨 준다.',{trust:2},'staff')],follow:{quiet:{days:6,text:'복도가 시끄러울 때면 안쪽 자리에서 쉰다. 직원은 편히 쉬는 시간을 피해 청소한다.',delta:{comfort:3}},staff:{days:8,text:'같은 직원의 발소리가 오면 고개를 든다. 가림 천 너머로 잠깐 확인한 뒤 다시 눕는다.',delta:{trust:3}}}},
{id:'rural-distance',min:180,homes:['family','street'],condition:s=>['rural','village'].includes(s.worldModel.context.space),start:'밭길 건너에서 큰 가축이 몸을 돌린다. 사이에는 울타리가 있고 내 쪽 길은 넓게 비어 있다.',actions:[choice('detour','울타리에서 떨어진 길로 걷는다','큰 몸과 거리를 두고 밭길을 지났다. 가축은 울타리 안쪽에서 움직인다.',{comfort:2},'route'),choice('still','길 가장자리에서 잠깐 움직임을 멈춘다','큰 몸이 다른 쪽을 향하자 천천히 내 길로 돌아섰다.',{stress:-2},'watch')],follow:{route:{days:15,text:'밭길을 지날 때면 울타리 바깥 넓은 쪽으로 돈다. 급히 뛰지 않고 생활하던 길로 이어 간다.',delta:{comfort:2}},watch:{days:18,text:'가축이 움직이는 소리에 멈췄다가 충분히 멀어지면 다시 걷는다. 같은 길의 움직임을 익힌다.',delta:{stress:-2}}}},
{id:'clinic-handling',min:100,homes:['family','shelter'],condition:s=>s.environmentModel?.access.medical>=45&&s.log.some(e=>['vet-visit','clinical-diagnosis','preventive-visit','health-check'].includes(e.id)),start:'검진을 다녀온 뒤 돌아와 쉬던 자리에 이동장이 열려 있다. 돌보는 사람이 가까이 앉아 손을 낮추고 기다린다.',actions:[choice('hand','몸을 붙잡지 않는 손 쪽으로 코를 내민다','짧게 손을 확인한 뒤 물러났다. 다시 붙잡히지 않고 이동장 문이 열렸다.',{trust:2},'familiar'),choice('den','열린 이동장 안쪽으로 들어간다','안쪽 천에 몸을 붙였다. 사람이 잠깐 기다린 뒤 이동장을 조심히 든다.',{stress:-2},'carrier')],follow:{familiar:{days:40,text:'집에서 손이 어깨 가까이 왔다가 멈춘다. 짧게 닿고 쉬는 연습을 반복하며 몸을 맡기는 시간이 늘었다.',delta:{trust:2}},carrier:{days:25,text:'이동장은 집에서도 열린 채 놓여 있다. 병원에 가지 않는 날에도 안에 들어가 쉬었다.',delta:{comfort:3}}}},
{id:'aging-companion',min:2920,homes:['family'],start:'예전처럼 장난감을 길게 쫓지 않고 중간에 멈춘다. 사람이 장난감을 가까운 쪽에 놓고 바닥에 앉는다.',actions:[choice('nose','누운 채 코로 장난감을 밀어 본다','장난감이 조금 움직이자 앞발로 붙잡았다. 뛰지 않아도 짧게 놀이가 이어졌다.',{comfort:3},'gentle'),choice('quiet','놀이 대신 사람 옆에서 쉰다','손이 등을 천천히 지나갔다. 더 움직이지 않고 편한 자세로 눈을 감는다.',{familyBond:3},'rest')],follow:{gentle:{days:18,text:'요즘은 가까운 곳에서 장난감을 건드리고 자주 쉰다. 사람이 미끄러지지 않는 자리를 넓혀 준다.',delta:{comfort:3}},rest:{days:12,text:'오래 걷는 대신 짧게 나갔다 돌아온다. 쉬는 자리 가까이에 물과 익숙한 담요가 놓였다.',delta:{comfort:3}}}}
];
THREADS.push(...CARE_THREADS);
export function initThreads(s){s.threads??={version:1,used:[],arcs:[],next:s.day+70};return s.threads}
export function threadStep(s,{log,decision}){const t=initThreads(s);for(const a of t.arcs){if(a.stage!=='waiting')continue;const def=THREADS.find(x=>x.id===a.kind),follow=def?.follow[a.branch];if(a.area!==s.areaId||a.home!==s.home||!threadContextValid(s,def,a)){a.stage='closed';a.end=s.day;a.reason='context-changed';log(s,'thread-closed','지내는 곳이나 그 경험을 함께하던 상대가 달라졌다. 이전 자리에서 이어가던 일은 그곳의 기억으로 남았다.');Object.assign(s.log.at(-1),{storyId:a.id,actorId:a.actor});continue}if(s.day<a.next)continue;if(!follow){a.stage='closed';continue}if(s.medical.episode)continue;log(s,'thread-followup',follow.text);Object.assign(s.log.at(-1),{storyId:a.id,actorId:a.actor});for(const[k,v]of Object.entries(follow.delta)){const owner=k in s.needs?s.needs:s;owner[k]=Math.max(0,Math.min(100,owner[k]+v));};a.stage='complete';a.end=s.day;return true}
if(s.pending||s.day<t.next||s.medical.episode||s.clinical?.active)return false;const pool=THREADS.filter(d=>s.day>=d.min&&(d.max==null||s.day<=d.max)&&d.homes.includes(s.home)&&!t.used.includes(d.id)&&(!d.condition||d.condition(s)));if(!pool.length){t.next=s.day+30;return false}const d=pool[mix(s.seed+s.day,1240)%pool.length];const context={threadId:d.id,actor:threadActor(s,d),area:s.areaId,home:s.home,place:s.worldModel.context.label,cause:'thread-'+d.id};if(!decision(s,'thread:'+d.id,d.start,d.actions.map(o=>[o.id,o.text]),context))return false;s.pending.context=context;t.used.push(d.id);t.next=s.day+65;return true}
export function threadChoice(s,p,id,{log,remember}){if(!p.id.startsWith('thread:'))return false;const def=THREADS.find(x=>'thread:'+x.id===p.id),o=def?.actions.find(x=>x.id===id);if(!o||def.actor&&!def.actor(s)||!canResolveThread(s,p,id))return false;const t=initThreads(s),arc={id:`thread:${def.id}:${s.day}`,kind:def.id,stage:'waiting',branch:o.next,start:s.day,next:s.day+def.follow[o.next].days,actor:p.context?.actor||threadActor(s,def),area:s.areaId,home:s.home};t.arcs.push(arc);for(const[k,v]of Object.entries(o.delta)){const owner=k in s.needs?s.needs:s;owner[k]=Math.max(0,Math.min(100,owner[k]+v));};log(s,'thread-result',o.result);s.log.at(-1).storyId=arc.id;remember(s,'thread:'+def.id+':'+o.next);return true}
export function validThread(id){return THREADS.some(d=>'thread:'+d.id===id)}
export function validateThreads(s){if(s.pending?.id?.startsWith('thread:')&&s.pending.context&&!s.pending.options.every(o=>canResolveThread(s,s.pending,o.id)))throw Error('이야기 상대와 맞지 않는 선택 기록');if(s.threads&&(!Array.isArray(s.threads.used)||!Array.isArray(s.threads.arcs)||!s.threads.arcs.every(a=>typeof a.id==='string'&&THREADS.some(d=>d.id===a.kind&&d.follow[a.branch])&&['waiting','complete','closed'].includes(a.stage)&&Number.isInteger(a.next)&&a.next>=a.start)))throw Error('손상된 연속 이야기');}

function threadActor(s,d){if(d.actor)return d.actor(s);if(d.id==='sibling-distance')return s.relations.find(r=>r.kind==='sibling'&&r.active)?.id||null;return s.home==='street'?'environment:'+s.areaId:s.caregiverId;}
function threadContextValid(s,d,a){if(!d)return false;if(d.continues)return !!d.continues(s,a);if(!a.actor)return true;if(a.actor.startsWith('environment:'))return a.actor==='environment:'+s.areaId;if(a.actor.startsWith('sibling-'))return s.relations.some(r=>r.id===a.actor&&r.active);return a.actor===s.caregiverId&&s.humans.some(h=>h.id===a.actor&&h.area===s.areaId);}
export function canResolveThread(s,p,id){const d=THREADS.find(d=>'thread:'+d.id===p.id);if(!d?.actions.some(o=>o.id===id))return false;if(!p.context)return true;return p.context.threadId===d.id&&p.context.area===s.areaId&&p.context.home===s.home&&p.context.actor===threadActor(s,d)&&threadContextValid(s,d,p.context);}
